#' @return External pointer to HingeFeature object
#' @export
create_hinge_feature <- function(values, name, min_knot, max_knot, is_reverse = FALSE) {
    .Call(`_maxentcpp_create_hinge_feature`, values, name, min_knot, max_knot, is_reverse)
}

