#' Compute Permutation Importance
#'
#' Measures how much each environmental variable contributes to model
#' prediction quality by permuting each variable and measuring AUC drop.
#'
#' @param fs_ptr         External pointer to a FeaturedSpace object.
#' @param grid_ptrs      List of external pointers to Grid<float> objects.
#' @param feature_names  Character vector of environment variable names.
#' @param presence_rows  Integer vector of presence site row indices.
#' @param presence_cols  Integer vector of presence site column indices.
#' @param absence_rows   Integer vector of absence site row indices.
#' @param absence_cols   Integer vector of absence site column indices.
#' @param seed           Random seed for reproducibility.
#' @return A data.frame with columns: name, permutation_importance.
#' @export
compute_permutation_importance <- function(fs_ptr, grid_ptrs, feature_names, presence_rows, presence_cols, absence_rows, absence_cols, seed = 42L) {
    .Call(`_maxentcpp_compute_permutation_importance`, fs_ptr, grid_ptrs, feature_names, presence_rows, presence_cols, absence_rows, absence_cols, seed)
}

#' Compute Percent Contribution
#'
#' Computes variable contribution based on sum of absolute lambda values
#' for features derived from each variable.
#'
#' @param fs_ptr         External pointer to a FeaturedSpace object.
#' @param feature_names  Character vector of base variable names.
#' @return A data.frame with columns: name, contribution.
#' @export
compute_percent_contribution <- function(fs_ptr, feature_names) {
    .Call(`_maxentcpp_compute_percent_contribution`, fs_ptr, feature_names)
}

#' Compute Java-compatible Marginal Response Curve
#'
#' Like compute_response_curve() but applies the Java Maxent cloglog:
#'   cloglog_java = 1 - exp(-exp(H) * raw_java)
#'
#' This matches the response curves produced by Java Maxent and dismo.
#'
#' @param fs_ptr         External pointer to a FeaturedSpace object.
#' @param grid_ptrs      List of external pointers to Grid<float> objects.
#' @param feature_names  Character vector of environment variable names.
#' @param var_index      0-based index of the variable to vary.
#' @param n_steps        Number of steps across the variable range.
#' @return A data.frame with columns: value, prediction.
#' @export
compute_response_curve <- function(fs_ptr, grid_ptrs, feature_names, var_index, n_steps = 100L) {
    .Call(`_maxentcpp_compute_response_curve`, fs_ptr, grid_ptrs, feature_names, var_index, n_steps)
}

#' Compute Java-compatible Response Curve with Fixed Values
#'
#' Like compute_response_curve_fixed() but applies the Java Maxent cloglog:
#'   cloglog_java = 1 - exp(-exp(H) * raw_java)
#'
#' @param fs_ptr         External pointer to a FeaturedSpace object.
#' @param fixed_values   Numeric vector of fixed values for each variable.
#' @param feature_names  Character vector of environment variable names.
#' @param var_index      0-based index of the variable to vary.
#' @param var_min        Minimum value of the target variable.
#' @param var_max        Maximum value of the target variable.
#' @param n_steps        Number of steps.
#' @return A data.frame with columns: value, prediction.
#' @export
compute_response_curve_fixed <- function(fs_ptr, fixed_values, feature_names, var_index, var_min, var_max, n_steps = 100L) {
    .Call(`_maxentcpp_compute_response_curve_fixed`, fs_ptr, fixed_values, feature_names, var_index, var_min, var_max, n_steps)
}

#' Clamp Environmental Grids
#'
#' Restricts environmental variable values to the training range.
#' Returns clamped grids and a clamping indicator grid.
#'
#' @param grid_ptrs List of external pointers to Grid<float> objects.
#' @param var_mins  Numeric vector of minimum training values per variable.
#' @param var_maxs  Numeric vector of maximum training values per variable.
#' @return A named list with:
#'   \describe{
#'     \item{clamped_grids}{List of external pointers to clamped Grid<float>}
#'     \item{clamp_grid}{External pointer to Grid<float> with clamping magnitudes}
#'   }
#' @export
clamp_grids <- function(grid_ptrs, var_mins, var_maxs) {
    .Call(`_maxentcpp_clamp_grids`, grid_ptrs, var_mins, var_maxs)
}

#' Compute Variable Ranges from Grids
#'
#' Scans all valid cells to determine min/max of each variable.
#'
#' @param grid_ptrs List of external pointers to Grid<float> objects.
#' @return A data.frame with columns: min, max.
#' @export
compute_variable_ranges <- function(grid_ptrs) {
    .Call(`_maxentcpp_compute_variable_ranges`, grid_ptrs)
}

#' Compute MESS (Multivariate Environmental Similarity Surface)
#'
#' Measures how similar each cell is to the training environment.
#' Negative values indicate novel (non-analog) conditions.
#'
#' @param grid_ptrs         List of external pointers to Grid<float> objects.
#' @param reference_values  List of numeric vectors with reference values
#'   for each variable (e.g. values at training sites).
#' @param feature_names     Character vector of variable names.
#' @return A named list with:
#'   \describe{
#'     \item{mess_grid}{External pointer to Grid<float> with MESS values}
#'     \item{mod_grid}{External pointer to Grid<float> with MoD variable index (1-based)}
#'   }
#' @export
compute_mess <- function(grid_ptrs, reference_values, feature_names) {
    .Call(`_maxentcpp_compute_mess`, grid_ptrs, reference_values, feature_names)
}

#' Compute MESS from Min/Max Ranges
#'
#' Simplified MESS using only the min/max of reference data.
#'
#' @param grid_ptrs List of external pointers to Grid<float> objects.
#' @param var_mins  Numeric vector of minimum reference values.
#' @param var_maxs  Numeric vector of maximum reference values.
#' @return A named list with mess_grid and mod_grid (external pointers).
#' @export
compute_mess_range <- function(grid_ptrs, var_mins, var_maxs) {
    .Call(`_maxentcpp_compute_mess_range`, grid_ptrs, var_mins, var_maxs)
}

#' Compute AUC (Area Under the ROC Curve)
#'
#' Computes the Wilcoxon-Mann-Whitney AUC statistic from prediction scores
#' at presence and absence sites.
#'
#' @param presence Numeric vector of prediction scores at presence sites.
#' @param absence  Numeric vector of prediction scores at absence sites.
#' @return A named list with elements: auc, max_kappa, max_kappa_thresh.
#' @export
eval_auc <- function(presence, absence) {
    .Call(`_maxentcpp_eval_auc`, presence, absence)
}

#' Compute Pearson Correlation
#'
#' Computes Pearson correlation coefficient between two numeric vectors.
#'
#' @param x Numeric vector.
#' @param y Numeric vector (same length as x).
#' @return Correlation coefficient in [-1, 1].
#' @export
eval_correlation <- function(x, y) {
    .Call(`_maxentcpp_eval_correlation`, x, y)
}

#' Compute Log-Loss
#'
#' Computes average cross-entropy log-loss from predictions at
#' presence and absence sites.
#'
#' @param presence Numeric vector of prediction scores at presence sites.
#' @param absence  Numeric vector of prediction scores at absence sites.
#' @return Average log-loss value.
#' @export
eval_logloss <- function(presence, absence) {
    .Call(`_maxentcpp_eval_logloss`, presence, absence)
}

#' Compute Mean Squared Error
#'
#' Presence sites contribute (1-pred)^2, absence sites contribute pred^2.
#'
#' @param presence Numeric vector of prediction scores at presence sites.
#' @param absence  Numeric vector of prediction scores at absence sites.
#' @return Mean squared error.
#' @export
eval_square_error <- function(presence, absence) {
    .Call(`_maxentcpp_eval_square_error`, presence, absence)
}

#' Compute Misclassification Rate
#'
#' Fraction of misclassified samples at threshold 0.5.
#'
#' @param presence Numeric vector of prediction scores at presence sites.
#' @param absence  Numeric vector of prediction scores at absence sites.
#' @return Misclassification rate in [0, 1].
#' @export
eval_misclassification <- function(presence, absence) {
    .Call(`_maxentcpp_eval_misclassification`, presence, absence)
}

#' Full Model Evaluation
#'
#' Computes all evaluation metrics at once: AUC, correlation, log-loss,
#' squared error, misclassification, max kappa, and prevalence.
#'
#' @param presence Numeric vector of prediction scores at presence sites.
#' @param absence  Numeric vector of prediction scores at absence sites.
#' @return A named list with: auc, max_kappa, max_kappa_thresh,
#'   correlation, square_error, logloss, misclassification, prevalence.
#' @export
eval_model <- function(presence, absence) {
    .Call(`_maxentcpp_eval_model`, presence, absence)
}

#' Project Model onto Grids (Java-compatible raw output)
#'
#' Applies a trained FeaturedSpace model to produce Java Maxent "raw" scores:
#'   raw_java = exp(lp - lpNorm) / densityNorm
#'
#' This matches the raw output of the Java Maxent software and the dismo
#' R package.
#'
#' @param fs_ptr         External pointer to a FeaturedSpace object.
#' @param grid_ptrs      List of external pointers to Grid<float> objects.
#' @param feature_names  Character vector of environment variable names.
#' @return External pointer to a Grid<float> with Java raw scores.
#' @export
project_raw <- function(fs_ptr, grid_ptrs, feature_names) {
    .Call(`_maxentcpp_project_raw`, fs_ptr, grid_ptrs, feature_names)
}

#' Project Model onto Grids (Java-compatible cloglog output)
#'
#' Applies the Java Maxent cloglog formula:
#'   cloglog_java = 1 - exp(-exp(H) * raw_java)
#'
#' where H is the model entropy and raw_java is the normalised probability.
#' This matches the cloglog output of Java Maxent and dismo.
#'
#' @param fs_ptr         External pointer to a FeaturedSpace object.
#' @param grid_ptrs      List of external pointers to Grid<float> objects.
#' @param feature_names  Character vector of environment variable names.
#' @return External pointer to a Grid<float> with Java cloglog scores in [0, 1].
#' @export
project_cloglog <- function(fs_ptr, grid_ptrs, feature_names) {
    .Call(`_maxentcpp_project_cloglog`, fs_ptr, grid_ptrs, feature_names)
}

#' Project Model onto Grids (Java-compatible logistic output)
#'
#' Applies the Java Maxent logistic formula:
#'   logistic_java = (exp(H) * raw_java) / (1 + exp(H) * raw_java)
#'
#' where H is the model entropy and raw_java is the normalised probability.
#' This matches the logistic output of Java Maxent and dismo.
#'
#' @param fs_ptr         External pointer to a FeaturedSpace object.
#' @param grid_ptrs      List of external pointers to Grid<float> objects.
#' @param feature_names  Character vector of environment variable names.
#' @return External pointer to a Grid<float> with Java logistic scores in [0, 1].
#' @export
project_logistic <- function(fs_ptr, grid_ptrs, feature_names) {
    .Call(`_maxentcpp_project_logistic`, fs_ptr, grid_ptrs, feature_names)
}

#' Extract Java-compatible Raw Predictions at Sample Locations
#'
#' Gets Java Maxent raw scores (raw_java = exp(lp - lpNorm) / densityNorm)
#' at specific grid cell locations.
#'
#' @param fs_ptr         External pointer to a FeaturedSpace object.
#' @param grid_ptrs      List of external pointers to Grid<float> objects.
#' @param feature_names  Character vector of environment variable names.
#' @param rows           Integer vector of row indices.
#' @param cols           Integer vector of column indices.
#' @return Numeric vector of Java raw scores. NaN for NODATA cells.
#' @export
extract_predictions_raw <- function(fs_ptr, grid_ptrs, feature_names, rows, cols) {
    .Call(`_maxentcpp_extract_predictions_raw`, fs_ptr, grid_ptrs, feature_names, rows, cols)
}

